css:
/* The platform draws a plain title / date / cover above every post. The post banner component draws the real one. */
article > .bz-block:first-child{display:none}

body [data-bz-node="pst"]{background:#fff;padding:72px 0 88px}
body :where([data-bz-node="pst"]) .bz-block{padding:0}
body :where([data-bz-node="pst"]) .bz-container{padding:0;max-width:none}
body [data-bz-node="pst"]>.bz-container{max-width:var(--container);padding-inline:0}
body [data-bz-node="pst-row"]{display:grid;grid-template-columns:250px minmax(0,780px);gap:0 64px;justify-content:center;align-items:start}
body [data-bz-node="pst-row"]>.bz-col{grid-column:auto}
body [data-bz-node="pst-side"]{position:sticky;top:32px;align-self:start}
body [data-bz-node="pst-ctarow"]{display:block;margin-top:36px}
body [data-bz-node="pst-cta"]{border:1px solid #e4e4e2;padding:24px 22px 22px;background:#fff}
body [data-bz-node="pst-cta-h"] h3{font:700 14px/1.3 var(--font-heading);letter-spacing:.02em;text-transform:uppercase;color:var(--ink);margin:0 0 12px}
body [data-bz-node="pst-cta-t"] p{font:400 12.5px/1.65 var(--font-body);color:#555;margin:0}
body [data-bz-node="pst-cta-b"]{margin-top:16px}
body [data-bz-node="pst-cta-b"] .bz-btns{margin:0}
body [data-bz-node="pst-cta-b"] .bz-btn{padding:0;border:0;background:none;color:var(--ink);font:700 10.5px/1 var(--font-body);letter-spacing:.16em;text-transform:uppercase;text-decoration:none;gap:10px}
body [data-bz-node="pst-cta-b"] .bz-btn::after{content:"";width:13px;height:13px;background:currentColor;-webkit-mask:url(/icons/arrow-right.svg) center/13px no-repeat;mask:url(/icons/arrow-right.svg) center/13px no-repeat}

/* article column */
body [data-bz-node="pst-body"] .bz-text{max-width:none}
body [data-bz-node="pst-body"] .bz-block--text{margin:0 0 18px}
body [data-bz-node="pst-body"] .bz-block--text p{font:400 13.5px/26px var(--font-body);color:var(--ink);margin:0}
body [data-bz-node="pst-body"] .bz-block--text a{color:var(--accent);text-decoration:none}
body [data-bz-node="pst-body"] .bz-block--text a:hover{text-decoration:underline}
body [data-bz-node="pst-body"] .bz-block--heading{margin:54px 0 18px}
body [data-bz-node="pst-body"] .bz-block--heading:first-child{margin-top:0}
body [data-bz-node="pst-body"] .bz-block--heading h2{font:700 28px/1.12 var(--font-heading);letter-spacing:0;text-transform:uppercase;color:var(--ink);margin:0}
body [data-bz-node="pst-body"] .bz-block--bullet-list{margin:0 0 20px}
body [data-bz-node="pst-body"] .bz-block--buttons{margin:26px 0 0}
body [data-bz-node="pst-body"] .bz-block--buttons .bz-btns{margin:0;gap:12px}
body [data-bz-node="pst-body"] .bz-block--buttons .bz-btn{display:inline-flex;align-items:center;justify-content:center;height:46px;padding:0 26px;border:0;border-radius:2px;background:var(--accent);color:#fff;font:700 11px/1 var(--font-body);letter-spacing:.18em;text-transform:uppercase;text-decoration:none}
body [data-bz-node="pst-body"] .bz-block--buttons .bz-btn:hover{background:var(--accent-dark)}
body [data-bz-node="pst-body"] .bz-block--buttons + .bz-block--text{margin-top:28px}
body [data-bz-node="pst-body"] .bz-block--widget{margin:28px 0 0}
body [data-bz-node="pst-body"] .bz-faqs{display:block;border-top:1px solid #d8d8d6}
body [data-bz-node="pst-body"] .bz-faq{border:0;border-bottom:1px solid #d8d8d6;border-radius:0;background:transparent;padding:0}
body [data-bz-node="pst-body"] .bz-faq summary{list-style:none;position:relative;padding:20px 44px 20px 0;font:700 12.5px/1.5 var(--font-heading);letter-spacing:.02em;text-transform:uppercase;color:var(--ink);cursor:pointer}
body [data-bz-node="pst-body"] .bz-faq summary::-webkit-details-marker{display:none}
body [data-bz-node="pst-body"] .bz-faq summary::after{content:"+";position:absolute;right:6px;top:50%;transform:translateY(-50%);font:400 20px/1 var(--font-body);color:var(--ink)}
body [data-bz-node="pst-body"] .bz-faq[open] summary::after{content:"\2212"}
body [data-bz-node="pst-body"] .bz-faq__a{padding:0 44px 22px 0;margin:0;font:400 13px/1.8 var(--font-body);color:#555}

@media (max-width:1100px){
  body [data-bz-node="pst"]{padding:48px 24px 64px}
  body [data-bz-node="pst-row"]{grid-template-columns:minmax(0,1fr);gap:40px 0}
  body [data-bz-node="pst-side"]{position:static;order:2}
  body [data-bz-node="pst-body"]{order:1}
  body [data-bz-node="pst-body"] .bz-block--heading h2{font-size:24px}
}
@media (max-width:640px){
  body [data-bz-node="pst"]{padding:36px 20px 48px}
  body [data-bz-node="pst-body"] .bz-block--heading{margin:40px 0 14px}
  body [data-bz-node="pst-body"] .bz-block--heading h2{font-size:21px}
  body [data-bz-node="pst-body"] .bz-block--buttons .bz-btn{width:100%}
}
